// Рабочая модель Кейса 4: прошла margin-тест (0,593), recall@1 на повороте
// 0,967 на 30 сканах CORD. Предыдущая (amazon/titan-embed-image-v1) отдавала
// один и тот же вектор на разные картинки — см. README-part2.md.
const MODEL = 'nvidia/nemotron-3.5-embed-1b:free';
const payload = JSON.parse($input.first().json.payload);
// Одним вызовом: сначала вектор запроса, затем векторы индекса — одна модель,
// один эндпоинт, обе стороны сравнения в одном числовом пространстве.
const input = [payload.query.image, ...payload.index.map(s => s.image)];
return [{json: {
  model: MODEL,
  labels: {query: payload.query.label, index: payload.index.map(s => s.label)},
  body: {model: MODEL, input: input},
}}];

// Косинусное расстояние эмбеддингов — то, что сравнивается в этом кейсе.
// cos = 1 → векторы совпали по направлению; расстояние = 1 − cos.
function cos(a, b) {
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) { dot += a[i]*b[i]; na += a[i]*a[i]; nb += b[i]*b[i]; }
  return dot / (Math.sqrt(na) * Math.sqrt(nb));
}
const prep = $('Тело запроса: nemotron-3.5-embed-1b').first().json;
const resp = $input.first().json;
if (!resp.data) { throw new Error('эндпоинт не вернул векторы: ' + JSON.stringify(resp).slice(0, 300)); }
const vectors = resp.data.map(d => d.embedding);
const qvec = vectors[0];                       // вектор запроса
const indexVectors = vectors.slice(1);         // векторы проиндексированных сканов
const ranked = indexVectors
  .map((v, i) => { const s = cos(qvec, v); return {label: prep.labels.index[i], similarity: s, distance: 1 - s}; })
  .sort((a, b) => b.similarity - a.similarity);
const best = ranked[0];
const margin = ranked.length > 1 ? best.similarity - ranked[1].similarity : null;
const lines = ranked.map((r, i) => `${i + 1}. ${r.label} — сходство ${r.similarity.toFixed(4)}, расстояние ${r.distance.toFixed(4)}`);
const summary = `Запрос: ${prep.labels.query}\n`
  + `Модель: ${prep.model}; длина вектора: ${qvec.length} чисел\n`
  + `Сравниваем: косинусное расстояние вектора запроса до векторов ${ranked.length} проиндексированных сканов\n\n`
  + `Ближайший: ${best.label}\n`
  + `  сходство ${best.similarity.toFixed(4)}, расстояние ${best.distance.toFixed(4)}\n`
  + (margin === null ? '' : `  отрыв от второго: ${margin.toFixed(4)}\n`)
  + `\nВся выдача по убыванию сходства:\n${lines.join('\n')}`;
return [{json: {query: prep.labels.query, model: prep.model, dim: qvec.length,
  best_label: best.label, best_similarity: best.similarity, best_distance: best.distance,
  margin: margin, ranking: ranked, summary: summary}}];
